#include "pch.h"

#include "ext/Seams.h"
#include "ext/core/Banner.h"
#include "ext/core/UpdateCheck.h"
#include "ext/fg/dlssg/PresetLogRelay.h"
#include "ext/status/StatusFile.h"

// Generated by the ExtBuildInfo target of ext.props into $(IntDir)ext_gen\ (never committed)
#include "ext_buildinfo.h"

namespace ext::core
{
const char* ForkVersion() { return EXT_BUILD_DESCRIBE; }

const char* UpstreamBase() { return EXT_BUILD_UPSTREAM; }

void Banner()
{
    spdlog::warn("OptiScaler-FFXIV {} on upstream {}", ForkVersion(), UpstreamBase());

    // The upstream update check is off unless the player turned it on (UpdateCheck.h). The config load applies that; a launch without a
    // readable OptiScaler.ini never gets there, so the default is applied here as well, before CheckWorkingMode starts the check.
    ext::updatecheck::ApplyDefault();

    // The logger exists and nothing else is logging yet: the one safe moment to add the DLSS-G preset readout sink (WS2).
    ext::fg::preset::AttachLogRelay();

    // The status file session (start time, pid, DLL folder); its worker thread still starts on the first present.
    ext::status::OnStartup();

    // One line when [Bridge] FlushAfterSignal is on. The config load ran before this point and already published the
    // key, but it ran before the logger existed, so the line belongs here.
    ext::bridge::LogStartupState();
}
} // namespace ext::core
